import{_ as e,o,c as a,a3 as d}from"./chunks/framework.cNy3aYYk.js";const m=JSON.parse('{"title":"Email-only tenant password reset — Production Readiness","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Email-only tenant password reset — Production Readiness | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/email-only-tenant-password-reset-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Email-only tenant password reset — Production Readiness | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/email-only-tenant-password-reset-production-readiness"}]]},"headers":[],"relativePath":"deployment/email-only-tenant-password-reset-production-readiness.md","filePath":"deployment/email-only-tenant-password-reset-production-readiness.md","lastUpdated":1791556751000}'),s={name:"deployment/email-only-tenant-password-reset-production-readiness.md"};function r(n,t,i,l,c,p){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="email-only-tenant-password-reset-—-production-readiness" tabindex="-1">Email-only tenant password reset — Production Readiness <a class="header-anchor" href="#email-only-tenant-password-reset-—-production-readiness" aria-label="Permalink to &quot;Email-only tenant password reset — Production Readiness&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Scope</strong></td><td>Shared-host tenant forgot/reset (<code>/#/forgot-password</code>, <code>/#/reset-password/{token}</code>) resolve workspace from email like login</td></tr><tr><td><strong>Date</strong></td><td>2026-10-06</td></tr><tr><td><strong>E2E</strong></td><td>Headed Chrome <code>auth.forgot-reset.workflow.spec.ts</code> — <strong>passed</strong> (validation → unknown email → known email → reset → sign-in, one session). Auth project: forgot/reset smoke <strong>passed</strong>.</td></tr></tbody></table><h2 id="locked-scope" tabindex="-1">Locked scope <a class="header-anchor" href="#locked-scope" aria-label="Permalink to &quot;Locked scope&quot;">​</a></h2><p>Tenant Application password reset on a non-workspace host (<code>app.elosync.com</code>). Customer Portal picker flow and Central forgot-password (no workspace) are out of scope except that Central remains email-only.</p><h2 id="audit-report-2026-10-06" tabindex="-1">Audit report (2026-10-06) <a class="header-anchor" href="#audit-report-2026-10-06" aria-label="Permalink to &quot;Audit report (2026-10-06)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Resolution</th></tr></thead><tbody><tr><td>A1</td><td><strong>High</strong></td><td><code>InitializeTenancy</code> resolved email → tenant only for <code>tenant.auth.login</code>. Forgot/reset on the shared SPA returned <code>workspace_required</code></td><td>Fixed: email resolution also for <code>tenant.auth.forgot-password</code> and <code>tenant.auth.reset-password</code></td></tr><tr><td>A2</td><td><strong>High</strong></td><td>Unknown emails without a workspace leaked <code>workspace_required</code> (account enumeration)</td><td>Fixed: pass-through + generic success when tenancy is not initialized</td></tr><tr><td>A3</td><td><strong>High</strong></td><td>Tenant SPA still required a Workspace field when <code>workspace_host_bound</code> is false</td><td>Removed workspace from tenant forgot/reset pages; POST body is <code>{ email }</code></td></tr><tr><td>A4</td><td>Med</td><td>Reset form kept a stale hidden token after HashRouter navigated to a new <code>/reset-password/{token}</code> URL</td><td>Sync token/email from route + query; submit uses the current URL token</td></tr><tr><td>A5</td><td>Med</td><td>Playwright <code>auth</code> project did not honour <code>E2E_BROWSER_CHANNEL</code> (headed Chrome missing bundled Chromium)</td><td>Applied the same channel mapping as the <code>tenant</code> project</td></tr><tr><td>A6</td><td>Low</td><td>Empty-login e2e submitted Vite DEV-prefilled credentials instead of validating blank fields</td><td><code>LoginPage.clearCredentials()</code> before empty submit</td></tr><tr><td>A7</td><td>Info</td><td>Mobile forgot-password required workspace even though login is email-first</td><td>Workspace is optional; email alone submits</td></tr><tr><td>A8</td><td><strong>High</strong></td><td>Password-reset notifications were <code>ShouldQueue</code> on <code>emails</code>. Local <code>QUEUE_CONNECTION=database</code> had <strong>458</strong> stuck jobs (including resets) with no worker — token created, inbox empty. Central mail provider was also <code>log</code></td><td>Fixed: tenant / central / portal reset notifications send <strong>synchronously</strong> in the HTTP request. Ops still need a real mail provider (not <code>log</code>) for inbox delivery; other product mail still uses the <code>emails</code> queue</td></tr><tr><td>A9</td><td><strong>High</strong></td><td>Tenant forgot-password used workspace mail runtime config. Workspaces with custom mail received resets; workspaces on system/unset mail did not</td><td>Fixed: <code>CentralMail::apply()</code> before tenant/portal reset send so platform auth always uses Central Settings → Mail</td></tr></tbody></table><h2 id="verification-matrix" tabindex="-1">Verification matrix <a class="header-anchor" href="#verification-matrix" aria-label="Permalink to &quot;Verification matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Backend</th><th>Frontend</th><th>Docs</th><th>Mobile</th></tr></thead><tbody><tr><td>Email-only forgot (known user) sends reset mail</td><td>Pass (Pest)</td><td>Pass (headed e2e)</td><td>Pass</td><td>Optional workspace</td></tr><tr><td>Unknown email generic success, no <code>workspace_required</code></td><td>Pass (Pest)</td><td>Pass (headed e2e)</td><td>Pass</td><td>N/A</td></tr><tr><td>Email-only reset + login after</td><td>Pass (Pest)</td><td>Pass (headed e2e)</td><td>Pass</td><td>N/A</td></tr><tr><td>Client validation (empty / invalid / mismatch)</td><td>N/A</td><td>Pass (headed e2e)</td><td>Pass</td><td>N/A</td></tr><tr><td>No workspace field on shared-host tenant pages</td><td>N/A</td><td>Pass</td><td>Pass</td><td>Optional field</td></tr><tr><td>Reset URL token stays in sync on SPA navigation</td><td>N/A</td><td>Pass (A4)</td><td>Pass</td><td>N/A</td></tr></tbody></table><h2 id="go-live" tabindex="-1">Go-live <a class="header-anchor" href="#go-live" aria-label="Permalink to &quot;Go-live&quot;">​</a></h2><ol><li>Deploy Backend (<code>InitializeTenancy</code> + synchronous reset notifications + <strong>CentralMail</strong> for tenant/portal forgot-password).</li><li>Deploy Frontend (email-only forgot/reset + reset token URL sync).</li><li>Deploy Mobile (optional workspace on forgot-password).</li><li>Confirm Central <strong>Settings → Mail</strong> is a real provider (SMTP / Postmark / Mailgun), not <code>log</code> — forgot-password uses this Central provider for every workspace (not tenant custom mail).</li><li>Smoke <code>https://app.elosync.com/#/forgot-password</code> on a workspace <strong>without</strong> tenant mail configured: submit email; open reset mail from the Central From address; set password; sign in with email only.</li><li>Confirm Customer Portal <code>/#/portal/forgot-password</code> still uses email → company picker (portal emails are not globally unique).</li></ol><h2 id="pest-playwright" tabindex="-1">Pest / Playwright <a class="header-anchor" href="#pest-playwright" aria-label="Permalink to &quot;Pest / Playwright&quot;">​</a></h2><ul><li><code>php artisan test --compact tests/Unit/AuthPasswordResetNotificationSyncTest.php tests/Feature/Tenant/Auth/TenantPasswordResetUsesCentralMailTest.php tests/Feature/Tenant/Auth/TenantAuthTest.php tests/Feature/Tenant/Auth/PasswordResetParityTest.php tests/Feature/Tenant/Isolation/TenantIsolationTest.php</code></li><li><code>E2E_BROWSER_CHANNEL=chrome E2E_BASE_URL=http://localhost:5175 npm run test:e2e:auth:headed</code> (or the workflow spec alone)</li></ul>',12)])])}const u=e(s,[["render",r]]);export{m as __pageData,u as default};
